import json
from ghidra.app.decompiler import DecompInterface
prog = currentProgram
out = {"sha256": str(prog.getExecutableSHA256()), "program": str(prog.getName())}
fm = prog.getFunctionManager()
addrs = ["0x142291230", "0x14229a7f0", "0x141218e30"]
results = {}
d = DecompInterface()
try:
    d.openProgram(prog)
    for a in addrs:
        monitor.checkCancelled()
        addr = prog.getAddressFactory().getAddress(a)
        f = fm.getFunctionAt(addr)
        if f is None:
            results[a] = {"error": "function absent"}
            continue
        r = d.decompileFunction(f, 120, monitor)
        entry = {"name": str(f.getName()), "body": str(f.getBody()),
                 "signature": str(f.getSignature())}
        if not r.decompileCompleted():
            entry["error"] = str(r.getErrorMessage())
        else:
            entry["decompiled"] = r.getDecompiledFunction().getC()
        results[a] = entry
finally:
    d.dispose()
out["functions"] = results
print(json.dumps(out))
